head.b:skin:

    /*
    <Group description="🎨 Cores do Tema (Pop Retro)" selector=":root">
      <Variable name="cor.primaria" description="Cor Principal (Destaques)" type="color" default="#FF4500" value="#FF4500"/>
      <Variable name="cor.secundaria" description="Cor Secundária (Efeito Matrix)" type="color" default="#00FF41" value="#00FF41"/>
      <Variable name="cor.fundo" description="Cor de Fundo (Background)" type="color" default="#F4F4F4" value="#F4F4F4"/>
      <Variable name="cor.borda" description="Cor das Bordas dos Cartuchos" type="color" default="#000000" value="#000000"/>
    </Group>
    */

    /* * SOFTLOAD ENGINE V6 - 100% DRAFT EDITABLE */
    :root {
      --primary: $(cor.primaria);
      --secondary: $(cor.secundaria);
      --bg-light: $(cor.fundo);
      --border-pixel: 4px solid $(cor.borda);
      --font-pixel: 'Press Start 2P', cursive;
    }

    body { background-color: var(--bg-light); color: #000; font-family: 'Segoe UI', sans-serif; overflow-x: hidden; }
    .retro-font { font-family: var(--font-pixel); font-size: 0.75rem; line-height: 1.5; }

    /* --- SISTEMA DE ANIMAÇÃO REVEAL --- */
    .reveal { opacity: 0; transform: translateY(30px); transition: 0.6s steps(5); }
    .reveal.active { opacity: 1; transform: translateY(0); }

    /* --- HEADER & LOGO --- */
    header { border-bottom: var(--border-pixel); background: #fff; }
    .logo-switcher {
      width: 150px; height: 150px; margin: 0 auto;
      background-size: contain; background-repeat: no-repeat; background-position: center;
      image-rendering: pixelated; cursor: pointer; transition: transform 0.1s steps(2);
    }
    .logo-switcher:hover { transform: scale(1.05); }
    .cta-blink { animation: blink 1s steps(2) infinite; color: #777; }
    @keyframes blink { 0% { opacity: 1; } 100% { opacity: 0; } }

    /* --- LANDING CARDS & RPG UI --- */
    .pixel-card {
      background: #fff; border: var(--border-pixel);
      box-shadow: 6px 6px 0px #000; padding: 25px; height: 100%;
      transition: 0.1s steps(2);
    }
    .pixel-card:hover { transform: translate(-4px, -4px); box-shadow: 10px 10px 0px var(--primary); }

    .btn-pixel {
      background: var(--primary); color: #fff !important;
      border: var(--border-pixel); box-shadow: 4px 4px 0px #000;
      padding: 10px 20px; text-decoration: none; display: inline-block;
      font-family: var(--font-pixel); font-size: 0.6rem;
    }
    .btn-pixel:active { transform: translate(4px, 4px); box-shadow: 0px 0px 0px #000; }

    /* --- NPC TESTIMONIALS --- */
    .npc-dialogue { display: flex; gap: 20px; margin-bottom: 30px; }
    .npc-sprite { width: 70px; height: 70px; border: var(--border-pixel); background: #fff; flex-shrink: 0; }
    .speech-bubble { 
      background: #fff; border: var(--border-pixel); padding: 15px; 
      position: relative; box-shadow: 4px 4px 0px #000; width: 100%;
    }

    /* --- MAIN POST CRT EFFECT --- */
    .crt-container { position: relative; border: var(--border-pixel); overflow: hidden; background: #000; }
    .scanlines {
      position: absolute; top: 0; left: 0; width: 100%; height: 100%;
      background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.1) 50%);
      background-size: 100% 4px; z-index: 2; pointer-events: none;
    }
    .glitch-title { cursor: pointer; }

    /* --- CLEANUP NATIVO --- */
    header h1, header h2, .widget h2.title, #navbar-iframe, .quickedit { display: none !important; }

    /* ==========================================================================
       PADRONIZAÇÃO AUTOMÁTICA DE GADGETS NATIVOS DO BLOGGER
       ========================================================================== */

    /* 1. Correção: Ocultar o título APENAS no header, mas mostrar no resto do blog */
    header h1, header h2, header .widget h2.title { display: none !important; }
    .sidebar .widget h2.title, main .widget h2.title { display: block !important; }

    /* 2. O "Cartucho" Automático (Bordas e Fundo) */
    .sidebar .widget, .footer .widget {
      background: #fff;
      border: var(--border-pixel);
      box-shadow: 6px 6px 0px #000;
      padding: 20px;
      margin-bottom: 30px;
      overflow: hidden; /* Evita que imagens grandes quebrem a caixa */
    }

    /* 3. Título do Gadget (Estilo Status Screen) */
    .widget h2.title {
      font-family: var(--font-pixel);
      font-size: 0.7rem;
      color: #000;
      border-bottom: 4px double #000;
      padding-bottom: 10px;
      margin-bottom: 15px;
      text-transform: uppercase;
      line-height: 1.4;
    }

    /* 4. Estilização de Menus/Listas Nativas (Marcadores, Arquivos) */
    .widget-content ul {
      list-style: none;
      padding-left: 0;
      margin: 0;
    }

    .widget-content ul li {
      padding: 10px 0;
      border-bottom: 1px dashed #ccc;
      font-family: 'Segoe UI', sans-serif;
      font-size: 0.85rem;
      display: flex;
      align-items: center;
    }

    .widget-content ul li:last-child {
      border-bottom: none;
    }

    /* O cursor clássico do RPG antes de cada item do menu */
    .widget-content ul li::before {
      content: ">";
      font-family: var(--font-pixel);
      color: var(--primary);
      margin-right: 10px;
      font-size: 0.6rem;
      animation: blink 1.5s steps(2) infinite; /* Pisca sutilmente */
    }

    /* 5. Links Nativos e Imagens dentro dos Gadgets */
    .widget-content a {
      color: #333;
      text-decoration: none;
      transition: color 0.2s, padding-left 0.2s;
    }

    .widget-content a:hover {
      color: var(--primary);
      padding-left: 5px; /* Efeito de seleção de menu */
    }

    .widget-content img {
      max-width: 100%;
      height: auto;
      border: 2px solid #000;
      image-rendering: pixelated;
    }

/*---------------------------------------------------------
  COMPONENTE: VÍDEO RESPONSIVO (16:9 PREMIUM)
-----------------------------------------------------------*/
.mag-video-wrapper {
    position: relative;
    width: 100%;
    padding-bottom: 56.25%; /* Matemática exata para a proporção 16:9 */
    height: 0;
    border-radius: var(--radius, 12px); /* Arredondamento premium */
    overflow: hidden;
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.08); /* Sombra elegante */
    margin: 2rem 0; /* Espaçamento para respirar no texto */
    background-color: #000; /* Fundo preto enquanto o vídeo carrega */
}

.mag-video-wrapper iframe {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    border: none;
}

b:includable.script:
function googleTranslateElementInit() {
  new google.translate.TranslateElement({
    pageLanguage: '',
    autoDisplay: 'true',
    layout: google.translate.TranslateElement.InlineLayout.
  }, 'google_translate_element');
}

body.script:
//
document.addEventListener('DOMContentLoaded', () => {

  // 1. LOGO SWAP ENGINE
  const logo = document.getElementById('main-logo-img');
  if(logo) {
    const p = logo.getAttribute('data-primary'), h = logo.getAttribute('data-hover');
    logo.addEventListener('mouseenter', () => logo.style.backgroundImage = `url('${h}')`);
    logo.addEventListener('mouseleave', () => logo.style.backgroundImage = `url('${p}')`);
  }

  // 2. TYPEWRITER EFFECT PARA NPCs
  const typeWriter = (el) => {
    const text = el.innerHTML; el.innerHTML = ''; let i = 0;
    const interval = setInterval(() => {
      if(i < text.length) { el.innerHTML += text.charAt(i); i++; }
      else clearInterval(interval);
    }, 30);
  };

  // 3. TITLE GLITCH EFFECT (MAIN POST)
  document.querySelectorAll('.glitch-title a').forEach(title => {
    title.addEventListener('mouseover', () => {
      if(!title.dataset.original) title.dataset.original = title.innerText;
      let iterations = 0;
      const interval = setInterval(() => {
        title.innerText = title.innerText.split("")
          .map((char, index) => {
            if(index < iterations) return title.dataset.original[index];
            return String.fromCharCode(65 + Math.floor(Math.random() * 26));
          }).join("");
        if(iterations >= title.dataset.original.length) clearInterval(interval);
        iterations += 1/2;
      }, 30);
    });
  });

  // 4. REVEAL & TYPEWRITER OBSERVER
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('active');
        const tw = entry.target.querySelector('[data-typewriter]');
        if(tw && !tw.classList.contains('typed')) {
          typeWriter(tw); tw.classList.add('typed');
        }
      }
    });
  }, { threshold: 0.1 });

  // Garante que os componentes editados no Draft recebam o observer
  document.querySelectorAll('.reveal, article').forEach(el => {
    el.classList.add('reveal');
    observer.observe(el);
  });
});
//
